package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class TypedRelationshipsBrowserAcceptance {
 static void click(Page p,String name){p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName(name).setExact(true)).press("Enter");}
 static void run(BrowserTest h)throws Exception {
  String source,target;try(var db=h.store.open()){PlatformFoundationTest.bind(db);source=Service.create(db,"cmdb_ci",map("short_description","Customer portal <script>"),"admin").get("sys_id").toString();target=Service.create(db,"cmdb_ci",map("short_description","Production hosting platform"),"admin").get("sys_id").toString();db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var context=browser.newContext()){
   var page=context.newPage();h.login(page,"admin");page.navigate(h.base()+"/admin/relationship-types");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Define another relationship type")).press("Enter");page.getByLabel("Source record table").selectOption("cmdb_ci");page.getByLabel("Target record table").selectOption("cmdb_ci");page.getByLabel("Forward label").fill("Runs on <script>");page.getByLabel("Inverse label").fill("Hosts applications");page.getByLabel("Dependency impact").selectOption("true");page.getByLabel("Type availability").selectOption("true");click(page,"Save relationship type");String typeUrl=page.url();page.navigate(h.base()+"/record/cmdb_ci/"+source);page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("View typed relationships").setExact(true)).press("Enter");click(page,"Choose target for Runs on <script>");page.getByLabel("Search related records").fill("Production hosting");click(page,"Search records");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Production hosting platform").setExact(true)).press("Enter");assertThat(page.getByRole(AriaRole.HEADING,new Page.GetByRoleOptions().setName("Add this relationship"))).isVisible();assertThat(page.locator("main")).containsText("Customer portal <script>");page.getByLabel("Reason for this relationship change").fill("Verified the production hosting dependency <script>");ReleaseBrowserAcceptance.accessible(page);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/relationship-review-light.png")).setFullPage(true));click(page,"Apply reviewed relationship");assertThat(page.locator("main")).containsText("Active · Link revision 1");page.navigate(h.base()+"/record/cmdb_ci/"+target+"/impact");assertThat(page.locator("main")).containsText("Customer portal <script>");page.navigate(h.base()+"/record/cmdb_ci/"+target+"/relations");assertThat(page.locator("main")).containsText("Hosts applications");page.locator("details summary").press("Enter");assertThat(page.locator("details")).containsText("Verified the production hosting dependency <script>");click(page,"Dark mode");page.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(page);assertEquals(false,page.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(page.locator("main script")).hasCount(0);page.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/relationship-inverse-dark.png")).setFullPage(true));
   page.navigate(typeUrl);page.getByLabel("Type availability").selectOption("false");click(page,"Save relationship type");page.navigate(h.base()+"/record/cmdb_ci/"+target+"/relations");page.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Review removal")).press("Enter");page.getByLabel("Reason for this relationship change").fill("Retired the confirmed hosting dependency");click(page,"Apply reviewed removal");assertThat(page.locator("main")).containsText("Removed · Link revision 2");page.locator("details summary").press("Enter");assertThat(page.locator("details")).containsText("Retired the confirmed hosting dependency");page.navigate(h.base()+"/record/cmdb_ci/"+target+"/impact");assertThat(page.locator("main")).not().containsText("Customer portal <script>");
  }
 }
}
